/* ---------- Detection ---------- */
function normalizeLang(tag) {
    if (!tag) return null;
    const t = tag.toLowerCase().replace('_', '-');
    // Portuguese: treat every variant as pt-BR (our authored Portuguese).
    if (t.startsWith('pt')) return 'pt-BR';
    // Chinese: all variants map to our simplified set.
    if (t.startsWith('zh')) return 'zh';
    if (t.startsWith('es')) return 'es';
    if (t.startsWith('ar')) return 'ar';
    const base = t.split('-')[0];
    if (I18N[t]) return t;
    if (I18N[base]) return base;
    return null;
}

function detectLanguage() {
    // 1. Explicit user override always wins.
    let saved;
    try { saved = normalizeLang(localStorage.getItem('match_lang')); } catch (_) {}
    if (saved && I18N[saved]) return saved;

    // 2. ?lang= query parameter (useful for shared/localized links).
    try {
        const qp = new URLSearchParams(window.location.search).get('lang');
        const fromQuery = normalizeLang(qp);
        if (fromQuery) return fromQuery;
    } catch (e) {}

    // 3. Device languages, in the user's own priority order.
    const candidates = (navigator.languages && navigator.languages.length)
        ? navigator.languages : [navigator.language || navigator.userLanguage];
    for (const c of candidates) {
        const hit = normalizeLang(c);
        if (hit) return hit;
    }
    return 'en';
}

/* ---------- Application ---------- */
function t(key, lang) {
    const L = lang || window.MATCH_LANG || 'en';
    return (I18N[L] && I18N[L][key]) || I18N['en'][key] || '';
}
window.t = t;

/**
 * Language is a display preference, not a separate document.
 *
 * Query-string ?lang= variants are the same HTML. Advertising them as
 * hreflang alternates (and rewriting canonical to include ?lang=) made
 * Google treat each language URL as a duplicate and pick its own
 * canonical — Search Console: "Duplicate, Google chose different canonical
 * than user" plus "Alternate page with proper canonical tag".
 *
 * Always keep the clean, query-free canonical. ?lang= still switches the
 * UI for people; it is not a crawlable language version.
 */
function syncCanonicalToLang() {
    try {
        const link = document.querySelector('link[rel="canonical"]');
        if (!link) return;
        const clean = link.href.split('?')[0].split('#')[0];
        if (link.getAttribute('href') !== clean) link.setAttribute('href', clean);
    } catch (e) { /* canonical stays as authored */ }
}

function applyTranslations(lang) {
    const meta = I18N_LANGS[lang] || I18N_LANGS['en'];
    window.MATCH_LANG = lang;
    syncCanonicalToLang();

    document.documentElement.setAttribute('lang', lang);
    document.documentElement.setAttribute('dir', meta.dir);
    document.body && document.body.classList.toggle('rtl-mode', meta.dir === 'rtl');

    document.querySelectorAll('[data-i18n]').forEach(el => {
        const val = t(el.getAttribute('data-i18n'), lang);
        if (val) el.textContent = val;
    });
    document.querySelectorAll('[data-i18n-html]').forEach(el => {
        const val = t(el.getAttribute('data-i18n-html'), lang);
        if (val) el.innerHTML = val;
    });
    // <optgroup> exposes its heading via the `label` property/attribute, not
    // textContent — a plain data-i18n scan silently misses it, which is why
    // the questionnaire's optgroup headings ("Film & Television" etc.) never
    // translated even where individual <option> text did.
    document.querySelectorAll('[data-i18n-label]').forEach(el => {
        const val = t(el.getAttribute('data-i18n-label'), lang);
        if (val) el.label = val;
    });
    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
        const val = t(el.getAttribute('data-i18n-placeholder'), lang);
        if (val) el.setAttribute('placeholder', val);
    });
    document.querySelectorAll('[data-i18n-aria]').forEach(el => {
        const val = t(el.getAttribute('data-i18n-aria'), lang);
        if (val) el.setAttribute('aria-label', val);
    });

    // Let other modules (result cards, cascading dropdowns) re-render in the new language.
    document.dispatchEvent(new CustomEvent('matchapp:langchange', { detail: { lang } }));
}

window.setLanguage = function(lang) {
    lang = normalizeLang(lang);
    if (!I18N[lang]) return;
    try { localStorage.setItem('match_lang', lang); } catch (_) {}
    applyTranslations(lang);
    const sel = document.getElementById('lang-switcher');
    if (sel) sel.value = lang;
};

function buildLanguageSwitcher() {
    const host = document.getElementById('lang-switcher-host');
    if (!host) return;
    const sel = document.createElement('select');
    sel.id = 'lang-switcher';
    sel.setAttribute('aria-label', 'Language');
    sel.className = 'lang-switcher';
    Object.entries(I18N_LANGS).forEach(([code, meta]) => {
        const o = document.createElement('option');
        o.value = code;
        o.textContent = `${meta.flag} ${meta.name}`;
        sel.appendChild(o);
    });
    sel.value = window.MATCH_LANG || 'en';
    sel.addEventListener('change', e => window.setLanguage(e.target.value));
    host.appendChild(sel);
}

// Run as early as possible so users never see an English flash first.
(function initI18n() {
    const lang = detectLanguage();
    window.MATCH_LANG = lang;
    document.documentElement.setAttribute('lang', lang);
    document.documentElement.setAttribute('dir', (I18N_LANGS[lang] || I18N_LANGS['en']).dir);

    // Retain the initial device/shared-link language on every later route too.
    try { localStorage.setItem('match_lang', lang); } catch (_) {}
    const boot = () => { applyTranslations(detectLanguage()); buildLanguageSwitcher(); };
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
    else boot();
})();window.addEventListener('storage', event => {
    if (event.key !== 'match_lang') return;
    const lang = normalizeLang(event.newValue);
    if (lang) { applyTranslations(lang); const sel = document.getElementById('lang-switcher'); if (sel) sel.value = lang; }
});
